"""Source text chunking service."""

import re
from dataclasses import dataclass


CHUNK_SIZE_WORDS = 500
CHUNK_OVERLAP_WORDS = 80

# Matches the page markers generated by the Day 3 PDF extractor.
PAGE_MARKER = re.compile(
    r"---\s*Page\s+(\d+)\s*---",
    flags=re.IGNORECASE,
)


@dataclass
class TextChunk:
    chunk_index: int
    text: str
    page_start: int
    page_end: int


def split_into_pages(extracted_text: str) -> list[tuple[int, str]]:
    """Split Day 3's extracted text into page-numbered blocks."""
    matches = list(PAGE_MARKER.finditer(extracted_text))

    if not matches:
        # Fallback for older documents without page markers.
        return [(1, extracted_text.strip())]

    pages = []

    for i, match in enumerate(matches):
        start = match.end()
        end = (
            matches[i + 1].start()
            if i + 1 < len(matches)
            else len(extracted_text)
        )

        page_number = int(match.group(1))
        page_text = extracted_text[start:end].strip()

        if page_text:
            pages.append((page_number, page_text))

    return pages


def chunk_document(
    extracted_text: str,
    chunk_size_words: int = CHUNK_SIZE_WORDS,
    overlap_words: int = CHUNK_OVERLAP_WORDS,
) -> list[TextChunk]:
    """Create overlapping chunks without crossing page boundaries."""
    if chunk_size_words < 1:
        raise ValueError("chunk_size_words must be positive.")

    if overlap_words < 0 or overlap_words >= chunk_size_words:
        raise ValueError(
            "overlap_words must be >= 0 and smaller than chunk_size_words."
        )

    chunks = []
    chunk_index = 0
    step = chunk_size_words - overlap_words

    for page_number, page_text in split_into_pages(extracted_text):
        words = page_text.split()

        for start in range(0, len(words), step):
            selected_words = words[start : start + chunk_size_words]

            if not selected_words:
                break

            text = " ".join(selected_words).strip()

            if text:
                chunks.append(
                    TextChunk(
                        chunk_index=chunk_index,
                        text=text,
                        page_start=page_number,
                        page_end=page_number,
                    )
                )
                chunk_index += 1

            if start + chunk_size_words >= len(words):
                break

    return chunks
